sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float width;
uniform float join;
uniform float position;
layout(color) uniform half4 strokeColor;
layout(color) uniform half4 secondColor;
uniform float gradientMix;
uniform float gradAngle;
uniform float strokeOpacity;
uniform float opacity;
float4 texT(float2 p) {
    return float4(image.eval(p));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = texT(coord);
    float amax = c.a;
    for (int k = 0; k < 3; k++) {
        float rr = width * (float(k) + 1.0) / 3.0 * (position < 0.5 ? 1.0 : 0.5);
        for (int i = 0; i < 12; i++) {
            float a = float(i) * 0.5235988;
            float2 off = float2(cos(a), sin(a));
            if (join > 0.5) off = off / max(abs(off.x), abs(off.y));
            amax = max(amax, texT(coord + off * rr).a);
        }
    }
    float st = saturate(amax - c.a) * strokeOpacity;
    float t = dot(coord / size - float2(0.5), float2(cos(radians(gradAngle)), sin(radians(gradAngle)))) + 0.5;
    float3 sc = mix(float3(strokeColor.rgb), mix(float3(strokeColor.rgb), float3(secondColor.rgb), saturate(t)), gradientMix);
    float4 r = c + float4(sc * st, st) * (1.0 - c.a);
    return fin(c, r, opacity);
}
